/* @lc app=leetcode id=3600 lang=kotlin */ class Solution { fun find(p: IntArray, x: Int): Int = generateSequence(x) { if (p[it] == it) null else p[it] }.toList().let { path -> path.last().also { r -> path.forEach { p[it] = r } } } fun ok(n: Int, edges: Array<IntArray>, k: Int, S: Int): Boolean = IntArray(n) { it }.let { p -> edges.filter { it[3] == 1 }.let { must -> must.all { it[2] >= S && (find(p, it[0]) != find(p, it[1])).also { d -> if (d) p[find(p, it[0])] = find(p, it[1]) } } && edges.filter { it[3] == 0 && it[2] >= S }.forEach { e -> if (find(p, e[0]) != find(p, e[1])) p[find(p, e[0])] = find(p, e[1]) }.let { edges.filter { it[3] == 0 && it[2] < S && 2 * it[2] >= S }.count { e -> (find(p, e[0]) != find(p, e[1])).also { d -> if (d) p[find(p, e[0])] = find(p, e[1]) } }.let { up -> up <= k && (0 until n).map { find(p, it) }.distinct().size == 1 } } } } fun maxStability(n: Int, edges: Array<IntArray>, k: Int): Int = if (!ok(n, edges, k, 1)) -1 else generateSequence(1 to 200000) { (lo, hi) -> if (lo >= hi) null else ((lo + hi + 1) / 2).let { mid -> if (ok(n, edges, k, mid)) mid to hi else lo to mid - 1 } }.last().first }